// opcodeEntry maps a language opcode to the image opcode with the same
// operands, inputs then outputs as A, B and C.
type opcodeEntry struct {
	opcodeEntryName    string
	opcodeEntryOpcode  ir.Opcode
	opcodeEntryInputs  int
	opcodeEntryOutputs int
}

